//! The faces of the DirectWrite backend against real Qt 6.12 on Windows: font simulations and the
//! member of a font collection (`tests/data/directwrite_faces_golden.txt`, regenerated by
//! `tests/data/gen_directwrite_faces_golden.py`).
//!
//! What this pins (Qt: `qwindowsdirectwritefontdatabase.cpp` `fontEngine`,
//! `qwindowsfontenginedirectwrite.cpp`):
//! * a request for a weight from DemiBold up gets `DWRITE_FONT_SIMULATIONS_BOLD` when the face
//!   found is lighter, and a request for an italic style gets `DWRITE_FONT_SIMULATIONS_OBLIQUE`
//!   when the face is upright: the advances (`QFontMetricsF::horizontalAdvance`,
//!   `averageCharWidth`), the A8 glyph bitmaps (`QRawFont::alphaMapForGlyph`) and whole strings
//!   (`QPainter::drawText`, ClearType) of an application font and of Windows system fonts that lack
//!   the weight or style (Tahoma italic, MS Gothic, Impact bold, SimSun and MingLiU bold), at
//!   device pixel ratios 1 and 1.25;
//! * the face of a font collection is the one the family names, and the shaper reads the same one
//!   (Yu Gothic UI, MS UI Gothic, MS PGothic, PMingLiU, NSimSun and the UI variants of
//!   Microsoft JhengHei and YaHei, whose ids differ from those of face 0).
//!
//! The system fonts are compared only when the file on this machine is the one the golden was
//! measured with (size and hash in the golden), so another Windows build skips them instead of
//! failing; the application font is in the repository and always runs.
//!
//! The ratio is process-wide state: the tests take turns.
#![cfg(windows)]

use ferrokit_gui::geometry::primitives::PointF;
use ferrokit_gui::paint::{Painter, Pen, Pixmap};
use ferrokit_gui::text::directwrite_face::is_available;
use ferrokit_gui::text::font::{Font, FontStyle, FontWeight, SharedFontData};
use ferrokit_gui::text::font_database::{
    resolve_font_engines_for_text_global, set_application_device_pixel_ratio,
    with_global_font_database,
};
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::smoothing::TextSmoothing;
use ferrokit_gui::tiny_skia::Color;
use std::sync::Mutex;

const GOLDEN: &str = include_str!("data/directwrite_faces_golden.txt");
const FIXTURE: &[u8] = include_bytes!("data/oracle_text.ttf");
const FIXTURE_FAMILY: &str = "FerrokitOracleText";
const GLYPH_TEXT: &str = "Hamburgefonts 0123";
const FIXTURE_GLYPH_TEXT: &str = "Hello Wor-ld 0123 AVTo";
const CJK_GLYPH_TEXT: &str = "日本語中文字テキスト";

/// The ratio and the font database are process-wide.
static LOCK: Mutex<()> = Mutex::new(());

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn text(id: &str) -> &'static str {
    match id {
        "a" => "Hello, World 123 AVAWTo",
        "b" => "The quick brown fox jumps over the lazy dog",
        "c" => "日本語テキスト中文字 ABC123",
        "fa" => "Hello Wor-ld 0123 AVTo",
        "fb" => "ACEFHJKMOPRTUWY",
        other => panic!("no text {other}"),
    }
}

fn font_of(family: &str, weight: u32, italic: bool, px: u32) -> Font {
    let mut font = Font::new(family, px as f32);
    font = font.with_weight(if weight >= 600 {
        FontWeight::Bold
    } else {
        FontWeight::Normal
    });
    if italic {
        font = font.with_style(FontStyle::Italic);
    }
    font
}

/// `QFontMetricsF::horizontalAdvance` in 1/64 px.
fn advance64(font: &Font, text: &str) -> i64 {
    let advance = FontMetrics::from_font(font).horizontal_advance_exact(text, font);
    let fixed = f64::from(advance) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{text:?} is not a whole number of 1/64 px"
    );
    fixed as i64
}

/// `QFontMetricsF::averageCharWidth` in 1/64 px.
fn average64(font: &Font) -> i64 {
    let fixed = f64::from(FontMetrics::from_font(font).average_char_width) * 64.0;
    assert_eq!(fixed, fixed.round(), "average width in 1/64 px");
    fixed as i64
}

/// Width, height and A8 bytes of every distinct character of `text`, in order, hashed.
fn glyph_hash(font: &Font, text: &str, dpr: f32) -> u64 {
    let engines = resolve_font_engines_for_text_global(font, text);
    let face = &engines[0].face;
    let mut seen = Vec::new();
    let mut blob = Vec::new();
    for ch in text.chars() {
        if seen.contains(&ch) {
            continue;
        }
        seen.push(ch);
        let (metrics, bits) = face.rasterize_scaled(face.glyph_index(ch), font.size, dpr);
        blob.extend_from_slice(&(metrics.width as u16).to_le_bytes());
        blob.extend_from_slice(&(metrics.height as u16).to_le_bytes());
        if metrics.width > 0 && metrics.height > 0 {
            assert_eq!(bits.len(), metrics.width * metrics.height);
            blob.extend_from_slice(&bits);
        }
    }
    fnv1a64(&blob)
}

/// `QPainter::drawText` of `text` with a black pen on white, ClearType, as the golden's.
fn draw(font: &Font, px: u32, text: &str, dpr: f32) -> (u32, u32, u64) {
    let (w, h) = (320.0 * dpr, (px * 2 + 12) as f32 * dpr);
    let mut pixmap =
        Pixmap::with_dpr(w.round() as u32, h.round() as u32, dpr).expect("pixmap of a golden case");
    pixmap.fill(Color::from_rgba8(255, 255, 255, 255));
    {
        let mut painter = Painter::begin(&mut pixmap);
        painter.set_text_smoothing(TextSmoothing {
            cleartype: true,
            gamma: 1.2,
        });
        painter.set_pen(Some(Pen::new(Color::from_rgba8(0, 0, 0, 255), 1.0)));
        painter.draw_text(PointF::new(6.0, px as f32 + 6.0), text, font);
    }
    (
        pixmap.physical_width(),
        pixmap.physical_height(),
        fnv1a64(pixmap.data()),
    )
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

/// Compares the measurement of one golden line: `fields` after the request fields, `Err` carrying
/// the report of a difference.
fn compare(label: &str, font: &Font, px: u32, dpr: f32, fields: &[&str]) -> Result<(), String> {
    let report = |got: String, want: String| {
        (got == want).then_some(()).ok_or(format!(
            "{label} {px} px x{dpr} {}: {got}, Qt {want}",
            fields.join(" ")
        ))
    };
    match fields[0] {
        "adv" => report(
            format!("{}/64", advance64(font, text(fields[1]))),
            format!("{}/64", fields[2]),
        ),
        "avg" => report(
            format!("{}/64", average64(font)),
            format!("{}/64", fields[1]),
        ),
        "glyphs" => {
            // `cjk` fonts have the CJK characters appended to the glyph text.
            let base = if font.family == FIXTURE_FAMILY {
                FIXTURE_GLYPH_TEXT
            } else {
                GLYPH_TEXT
            };
            let glyph_text = match fields[1] {
                "latin" => base.to_string(),
                "cjk" => format!("{base}{CJK_GLYPH_TEXT}"),
                other => panic!("golden glyph text {other}"),
            };
            report(
                format!("{:016x}", glyph_hash(font, &glyph_text, dpr)),
                format!("{:016x}", hex(fields[2])),
            )
        }
        "draw" => {
            let (w, h, got) = draw(font, px, text(fields[1]), dpr);
            report(
                format!("{w}x{h} {got:016x}"),
                format!("{}x{} {:016x}", fields[2], fields[3], hex(fields[4])),
            )
        }
        other => panic!("golden measurement {other}"),
    }
}

/// Runs the golden lines of the application font (`system == false`) or of the system fonts that
/// are on this machine unchanged. Returns (compared, failures).
fn run_golden(system: bool) -> (usize, Vec<String>) {
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut current_installed = false;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        if fields[0] == "sysfont" {
            let (size, hash) = (fields[2].parse::<usize>().unwrap(), hex(fields[3]));
            let dir = std::env::var("WINDIR").unwrap_or_else(|_| "C:/Windows".to_string());
            current_installed = std::fs::read(format!("{dir}/Fonts/{}", fields[1]))
                .ok()
                .is_some_and(|bytes| bytes.len() == size && fnv1a64(&bytes) == hash);
            if system && !current_installed {
                eprintln!("skipping {}: not installed as measured", fields[1]);
            }
            continue;
        }
        // `fix <dpr> <weight> <italic> <px> ...` or `sys <dpr> <family> <weight> <italic> <px> ...`
        let is_system = fields[0] == "sys";
        if is_system != system || (system && !current_installed) {
            continue;
        }
        let dpr: f32 = fields[1].parse().expect("dpr");
        let (family, rest) = if is_system {
            (fields[2].replace('_', " "), &fields[3..])
        } else {
            (FIXTURE_FAMILY.to_string(), &fields[2..])
        };
        let weight: u32 = rest[0].parse().expect("weight");
        let italic = rest[1] == "1";
        let px: u32 = rest[2].parse().expect("size");
        set_application_device_pixel_ratio(dpr);
        let font = font_of(&family, weight, italic, px);
        let label = format!("{family} {weight}{}", if italic { " italic" } else { "" });
        compared += 1;
        if let Err(report) = compare(&label, &font, px, dpr, &rest[3..]) {
            failures.push(report);
        }
    }
    set_application_device_pixel_ratio(1.0);
    (compared, failures)
}

fn register_fixture() {
    with_global_font_database(|db| {
        db.add_font_from_memory(FIXTURE_FAMILY, SharedFontData::from_vec(FIXTURE.to_vec()))
            .expect("the fixture font parses");
    });
}

#[test]
fn simulated_faces_of_an_application_font_are_identical_to_qt() {
    // DirectWrite's in-memory loader needs Windows 10 1703; on an older system the crate draws
    // with its outline backend, which these goldens do not describe.
    if !is_available() {
        return;
    }
    let _turn = LOCK.lock().unwrap_or_else(|e| e.into_inner());
    register_fixture();
    let (compared, failures) = run_golden(false);
    assert_eq!(compared, 3 * (8 + 4) * 6, "golden lines of the fixture");
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn simulated_faces_and_collection_members_of_system_fonts_are_identical_to_qt() {
    if !is_available() {
        return;
    }
    let _turn = LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let (compared, failures) = run_golden(true);
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
